(()=>{const items=[...document.querySelectorAll("[data-ar-motion]")];if(!items.length||!("IntersectionObserver"in window)||matchMedia("(prefers-reduced-motion: reduce)").matches)return;const states=new Map;const sync=el=>el.classList.toggle("ar-paused",!states.get(el)||document.hidden);const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{states.set(entry.target,entry.isIntersecting);if(entry.intersectionRatio>=.35)entry.target.classList.add("ar-running");sync(entry.target)}),{threshold:[0,.35]});items.forEach(el=>observer.observe(el));document.addEventListener("visibilitychange",()=>items.forEach(sync))})();